#pragma once

namespace tpublic
{

	class Manifest;

	namespace PostProcessItems
	{

		// Variants are generated by Run(), which happens after persistent ids are pruned. Their ids must be defined before
		// that, otherwise they're pruned and get new ids every build.
		void		DefineVariantIds(
						Manifest*			aManifest,
						PersistentIdTable*	aPersistentIdTable);
		void		Run(
						Manifest*			aManifest,
						PersistentIdTable*	aPersistentIdTable);

	}

}